using System;
using System.IO;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
public class CombatRailZone02ContractTests {
 const string Report="D:/Project/LASTRAIL/unity-project/QA/Unity1Artifacts/Reports/Exterior-20260914/";
 static string Hash(string path){using var h=System.Security.Cryptography.SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
 public static JObject Golden(){var a=JObject.Parse(File.ReadAllText(Report+"Closure01/presentation-closure-audit.json"));var e=JObject.Parse(File.ReadAllText(Report+"Closure01/second-final-closure-extension.json"));const string project="D:/Project/LASTRAIL/unity-project/";var m=new JObject{["profile"]="second-final-zone02-v1",["root"]=a["root"],["auditSha256"]=Hash(Report+"Closure01/presentation-closure-audit.json"),["extensionSha256"]=Hash(Report+"Closure01/second-final-closure-extension.json"),["selectionManifestSha256"]=new string('a',64),["roles"]=a["roles"],["bindings"]=a["rows"],["selectedResources"]=e["selectedResources"],["sourceFiles"]=new JArray(Directory.GetFiles(project+"Assets/_LASTRAIL","*.cs",SearchOption.AllDirectories).OrderBy(p=>p,StringComparer.Ordinal).Select(p=>new JObject{["path"]=p.Substring(project.Length).Replace(Path.DirectorySeparatorChar,'/'),["sha256"]=Hash(p)})),["zone02SelectionManifestSha256"]=Hash(Report+"zone02-selection-manifest.json"),["zone02Selection"]=JObject.Parse(File.ReadAllText(Report+"zone02-selection-manifest.json"))};var p=CombatRailPreparationTests.Golden();p["railPresentation"]=new JObject{["version"]="ce03-rail-presentation-v2",["manifestSha256"]="",["manifest"]=m};Rehash(p);return p;}
 static void Rehash(JObject p){p["railPresentation"]["manifestSha256"]=Ce03CommandContract.Sha(Ce03CommandContract.Canonical(p["railPresentation"]["manifest"]));var copy=(JObject)p.DeepClone();copy.Remove("preparationSha256");p["preparationSha256"]=Ce03CommandContract.Sha(Ce03CommandContract.Canonical(copy));}
 static void Verify(Ce03RailPreparation p){var type=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("Ce03RailPresentationBinding")).First(t=>t!=null);try{type.GetMethod("Verify").Invoke(null,new object[]{p});}catch(TargetInvocationException e){throw e.InnerException;}}
 [Test] public void ExplicitZone02KeepsGameplayExactAndBindsActualApprovedFiles(){var p=new Ce03RailPreparation(Golden(),"a",1);Assert.AreEqual(new Ce03RailPreparation(CombatRailPreparationTests.Golden(),"a",1).CreateModel(1).CaptureLocalState(),p.CreateModel(1).CaptureLocalState());Verify(p);}
 [Test] public void ActualServerZone02FixtureParsesWithoutGameplayChanges(){var p=CombatRailPreparationTests.Golden();p["railPresentation"]=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/unity-project/QA/Unity1Artifacts/Reports/Server2-Zone02-20260914/closure01-rail-presentation.json"));Rehash(p);var current=new Ce03RailPreparation(p,"a",1);Assert.AreEqual("0cb44eb11f4a96b3bc6f8aecea6d20f9067ee23f9f3ba0dcbaace39c02acc956",current.Presentation.Hash);Assert.AreEqual(new Ce03RailPreparation(CombatRailPreparationTests.Golden(),"a",1).CreateModel(1).CaptureLocalState(),current.CreateModel(1).CaptureLocalState());}
 [TestCase("unknown-role")][TestCase("bezel-type")][TestCase("source-hash")][TestCase("layout-source")][TestCase("role-mapping")][TestCase("downgrade")]
 public void RehashedForgedZone02IsRejected(string kind){var p=Golden();var m=(JObject)p["railPresentation"]["manifest"];var s=(JObject)m["zone02Selection"];var resources=(JArray)s["resources"];if(kind=="unknown-role"){var extra=(JObject)m["roles"][0].DeepClone();extra["role"]="approved.Unapproved";((JArray)m["roles"]).Add(extra);}if(kind=="bezel-type")resources.Single(r=>((JArray)r["roles"]).Any(v=>(string)v=="approved.ExteriorBezel"))["type"]="UnityEngine.TextAsset";if(kind=="source-hash")resources[0]["sourceRawSha256"]=new string('0',64);if(kind=="layout-source")resources.Single(r=>(string)r["type"]=="UnityEngine.TextAsset")["sourceFile"]="fake.json";if(kind=="role-mapping")resources[0]["roles"]=new JArray("approved.ExteriorBezel");if(kind=="downgrade")p["railPresentation"]["version"]="ce03-rail-presentation-v1";Rehash(p);Assert.Throws<ArgumentException>(()=>new Ce03RailPreparation(p,"a",1));}
 [Test] public void RehashedFalseSelectionFileDigestFailsPhysicalBinding(){var p=Golden();p["railPresentation"]["manifest"]["zone02SelectionManifestSha256"]=new string('0',64);Rehash(p);var prep=new Ce03RailPreparation(p,"a",1);Assert.Throws<InvalidOperationException>(()=>Verify(prep));}
 [Test] public void LegacyEnvelopeCannotSilentlyAccept216Roles(){var p=CombatRailPresentationContractTests.Golden();var role=(JObject)Golden()["railPresentation"]["manifest"]["roles"].Single(r=>(string)r["role"]=="approved.ExteriorBezel").DeepClone();var valid=(JObject)p["railPresentation"]["manifest"]["roles"][0];role["path"]=valid["path"];role["guid"]=valid["guid"];role["localFileId"]=valid["localFileId"];role["type"]=valid["type"];((JArray)p["railPresentation"]["manifest"]["roles"]).Add(role);Rehash(p);Assert.Throws<ArgumentException>(()=>new Ce03RailPreparation(p,"a",1));}
}
